.phone-wrap{position:sticky;top:16px}.phone-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.mode-toggle{display:flex;gap:4px;padding:4px;border:1px solid var(--border);background:var(--panel);border-radius:999px}.mode-toggle button{border:0;background:transparent;color:var(--muted);border-radius:999px;padding:8px 12px;cursor:pointer;font-weight:650}.mode-toggle button.active{background:var(--accent);color:var(--accentText)}.material-symbols-rounded{font-family:'Material Symbols Rounded';font-weight:normal;font-style:normal;font-size:20px;line-height:1;letter-spacing:normal;text-transform:none;display:inline-block;white-space:nowrap;word-wrap:normal;direction:ltr;-webkit-font-feature-settings:'liga';-webkit-font-smoothing:antialiased;vertical-align:middle}
.phone{width:100%;max-width:440px;aspect-ratio:0.49;border:7px solid #08090c;border-radius:42px;overflow:hidden;position:relative;margin:0 auto;background:var(--mock-bg);color:var(--mock-text);box-shadow:0 24px 70px #0005}.phone-status{height:34px;padding:8px 24px 0;display:flex;justify-content:space-between;font-size:11px;position:absolute;top:0;left:0;right:0;z-index:3;color:var(--mock-text)}.mock-map{position:relative;height:47%;min-height:220px;background-image:url("data:image/png;base64,");background-size:cover;background-position:center center;overflow:hidden;color:#333}.map-grid{position:absolute;inset:-10%;opacity:.7;background:repeating-linear-gradient(35deg,transparent 0 28px,var(--map-road) 29px 33px,transparent 34px 68px),repeating-linear-gradient(118deg,transparent 0 44px,var(--map-road2) 45px 49px,transparent 50px 82px)}.map-water{position:absolute;bottom:4%;right:-10%;width:68%;height:18%;background:var(--map-water);transform:rotate(-14deg);border-radius:50%;opacity:.8}.map-route{position:absolute;left:20%;top:22%;width:64%;height:45%;border:5px solid var(--route);border-left-color:transparent;border-bottom-color:transparent;border-radius:45% 55% 30% 50%;transform:rotate(28deg);filter:drop-shadow(0 1px 0 #fff7)}.map-pin{position:absolute;top:35%;left:49%;background:var(--mock-primary);color:var(--on-primary);padding:7px 10px;border-radius:10px;font-weight:800;box-shadow:0 3px 10px #0002}.map-pin small{display:block;font-size:9px}.mock-top-pill{position:absolute;top:9%;right:5%;border-radius:999px;background:var(--mock-primary);color:var(--on-primary);padding:8px 12px;font-weight:700}.mock-menu{position:absolute;top:9%;left:5%;width:40px;height:40px;display:grid;place-items:center;border-radius:50%;background:var(--mock-primary);color:var(--on-primary)}.mock-sheet{position:absolute;left:0;right:0;bottom:0;height:49%;border-radius:28px 28px 0 0;background:var(--mock-surface);padding:18px 15px 36px;box-shadow:0 -4px 20px #0001}.mock-search{height:44px;border-radius:999px;background:var(--mock-input);display:flex;align-items:center;gap:8px;padding:0 12px;color:var(--mock-muted);font-size:13px}.mock-search .schedule{margin-left:auto;background:var(--mock-primary);color:var(--on-primary);border-radius:999px;padding:8px 10px;font-size:11px;font-weight:700}.mock-label{font-size:15px;font-weight:700;margin:18px 0 10px}.quick-row{display:flex;gap:15px}.quick-item{width:60px;text-align:center;font-size:11px;color:var(--mock-text)}.quick-circle{height:50px;width:50px;margin:0 auto 5px;border-radius:50%;display:grid;place-items:center;background:var(--mock-primary);color:var(--on-primary)}.quick-circle.alt{background:#8a62f5;color:#fff}.quick-circle.neutral{background:var(--mock-outline);color:var(--mock-text)}.promo-row{display:flex;gap:10px;margin-top:10px}.promo{height:80px;flex:1;border-radius:12px;background:linear-gradient(135deg,var(--mock-primary),var(--promo-end));display:grid;place-items:center;color:var(--on-primary);font-size:12px;font-weight:800}.promo.alt{background:linear-gradient(135deg,#d8a8a0,#725d53);color:white}.mock-nav{position:absolute;bottom:0;height:22px;left:0;right:0;background:var(--mock-surface);display:flex;justify-content:space-around;align-items:center;color:var(--mock-muted);font-size:12px}


.mock-map .map-grid,.mock-map .map-water,.mock-map .map-route{display:none!important}
.mock-map .phone-status{color:#343434;text-shadow:0 1px 2px #fff}
.mock-map .mock-menu{background:var(--mock-primary);color:var(--on-primary)}
.mock-map .mock-top-pill{background:var(--mock-primary);color:var(--on-primary)}

.screen-selector-label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px;font-weight:600}

.screen-selector-wrap{position:relative;display:block;width:100%;margin:0 0 14px;padding:10px 12px 12px;border:1px solid var(--border);border-radius:14px;background:var(--panel);box-sizing:border-box}
.screen-selector-label{display:block;font-size:11px;letter-spacing:.08em;color:var(--muted);margin:0 0 8px;font-weight:750}
.screen-toggle{display:flex!important;align-items:center;gap:7px;flex-wrap:wrap;margin:0!important;visibility:visible!important;opacity:1!important}
.screen-toggle button{display:inline-flex;align-items:center;justify-content:center;gap:5px;border:1px solid var(--border);background:var(--panel2);color:var(--text);border-radius:999px;padding:8px 12px;font-size:12px;font-weight:650;cursor:pointer;white-space:nowrap}
.screen-toggle button.active{background:var(--accent);color:var(--accentText);border-color:var(--accent)}
.screen-toggle .material-symbols-rounded{font-size:16px}
@media(max-width:700px){.screen-toggle button{flex:1;padding:8px 7px}.screen-selector-wrap{margin-bottom:12px}}


/* Screen switching: show exactly one mobile screen inside the device frame. */
#phonePreview{position:relative;isolation:isolate}
#phonePreview[data-screen="home"] .mock-map,
#phonePreview[data-screen="home"] .mock-sheet{display:block}
#phonePreview[data-screen="home"] .mock-profile,
#phonePreview[data-screen="home"] .mock-drawer,
#phonePreview[data-screen="home"] .mock-splash{display:none}
#phonePreview[data-screen="profile"] .mock-map,
#phonePreview[data-screen="profile"] .mock-sheet,
#phonePreview[data-screen="profile"] .mock-drawer,
#phonePreview[data-screen="profile"] .mock-splash{display:none}
#phonePreview[data-screen="profile"] .mock-profile{display:block;z-index:3}
#phonePreview[data-screen="drawer"] .mock-map,
#phonePreview[data-screen="drawer"] .mock-sheet,
#phonePreview[data-screen="drawer"] .mock-profile,
#phonePreview[data-screen="drawer"] .mock-splash{display:none}
#phonePreview[data-screen="drawer"] .mock-drawer{display:block;z-index:3}
#phonePreview[data-screen="splash"] .mock-map,
#phonePreview[data-screen="splash"] .mock-sheet,
#phonePreview[data-screen="splash"] .mock-profile,
#phonePreview[data-screen="splash"] .mock-drawer,
#phonePreview[data-screen="splash"] .mock-nav{display:none}
#phonePreview[data-screen="splash"] .mock-splash{display:flex;z-index:4}
.mock-profile,.mock-drawer,.mock-splash{position:absolute;inset:0;overflow-y:auto}
.mock-profile{box-sizing:border-box;padding:44px 16px 42px;background:var(--mock-bg);color:var(--mock-text)}
.mock-profile .back{color:var(--mock-text);font-size:27px;line-height:1;margin-bottom:25px}
.mock-profile h2{font-size:25px;line-height:1.2;font-weight:500;margin:0 0 4px}
.mock-profile .sub{font-size:14px;line-height:1.35;color:var(--mock-muted);margin-bottom:25px}
.mock-profile .person{margin:0 0 28px}
.mock-profile .avatar{width:58px;height:58px;flex:none}
.mock-profile h3{font-size:15px;font-weight:650;margin:22px 0 11px}
.mock-profile .info-card{border:1px solid var(--mock-outline);border-radius:18px;padding:8px 14px;background:var(--mock-surface)}
.mock-profile .info-row{align-items:center;min-height:58px;gap:12px;padding:12px 0;color:var(--mock-muted)}
.mock-profile .info-row .material-symbols-rounded{font-size:22px;color:var(--mock-primary);flex:none}
.mock-profile .value{color:var(--mock-text);font-size:13px}
.mock-profile .pill{background:var(--mock-primary);color:var(--on-primary);font-weight:600}
.mock-profile .delete{font-weight:600;color:#D71935;margin:34px 0 12px}
.mock-drawer{box-sizing:border-box;background:var(--mock-surface);color:var(--mock-text);padding-bottom:40px}
.mock-drawer .drawer-hero{min-height:190px;padding:48px 18px 24px;background:linear-gradient(145deg,var(--mock-primary),var(--promo-end));color:var(--on-primary);border-radius:0 0 28px 0}
.mock-drawer .drawer-hero .material-symbols-rounded{font-size:30px;margin-bottom:14px}
.mock-drawer .drawer-item{min-height:57px;box-sizing:border-box;padding:14px 22px;gap:16px}
.mock-drawer .drawer-item .material-symbols-rounded{font-size:22px}
.mock-drawer .drawer-item.selected{background:var(--mock-outline);color:var(--mock-text);border-radius:0}
.mock-drawer .version{position:absolute;bottom:48px;left:0}
.mock-splash{box-sizing:border-box;align-items:stretch;justify-content:space-between;min-height:100%;padding:45px 20px 54px;background:var(--mock-primary);color:var(--on-primary)}
.mock-splash .statusbar{font-size:12px}
.mock-splash .brand{font-size:36px;line-height:1.05}
.mock-splash .brand small{border-top:2px solid var(--on-primary);padding-top:5px;margin-left:auto;width:78%;font-size:25px;line-height:1.1}
.mock-splash .welcome h2{font-size:28px;font-weight:500}
.mock-splash .welcome p{font-size:14px;line-height:1.4}
.mock-splash .get-started{background:var(--mock-surface);color:var(--mock-primary);min-height:54px}
#phonePreview[data-screen="home"] .mock-map{height:47%;min-height:220px}
#phonePreview[data-screen="home"] .mock-sheet{height:53%;overflow:hidden}


