/* Deliberately preserve phone/app preview tokens: --mock-primary and related values are set by palette logic. */

/* DARK WEBSITE THEME using the supplied B100-B700 neutrals; app previews stay independent. */
:root {
  color-scheme: dark;
  --bg: #1C1C1E !important;       /* b700 */
  --panel: #333333 !important;    /* b100 */
  --panel2: #4D4D4D !important;   /* b600 */
  --border: #666666 !important;   /* b200 / b300 */
  --text: #F0F0F0 !important;     /* b400 */
  --muted: #EBEBEB !important;    /* b500 */
  --accent: #E90000 !important;
  --accentText: #FFFFFF !important;
  --danger: #FF6B6B !important;
}
html { color-scheme: dark; background: #1C1C1E; }
body { background: #1C1C1E !important; color: #F0F0F0 !important; }
.panel, .screen-selector-wrap, .mode-toggle, .app-tabs,
.asset-controls, .asset-preview-panel, .asset-section,
.asset-card, .asset-editor, .asset-export, .card {
  background-color: #333333 !important;
  border-color: #666666 !important;
  color: #F0F0F0 !important;
}
input:not([type="color"]), select, textarea,
.asset-select, .asset-number, .asset-code-input, .asset-dropzone {
  background-color: #1C1C1E !important;
  color: #F0F0F0 !important;
  border-color: #666666 !important;
}
input::placeholder, textarea::placeholder { color: #EBEBEB !important; }
label, .fieldlabel, .eyebrow, .help, .note, .footer,
.asset-intro p, .asset-section-heading p, .screen-selector-label {
  color: #EBEBEB !important;
}
.app-tabs .app-tab, .screen-toggle button, .mode-toggle button,
.btn:not(.primary), .asset-platform-tab {
  background: #4D4D4D !important;
  color: #F0F0F0 !important;
  border-color: #666666 !important;
}
.app-tabs .app-tab.active, .screen-toggle button.active,
.mode-toggle button.active, .asset-platform-tab.active,
.btn.primary, button.primary, .logo {
  background: #E90000 !important;
  color: #FFFFFF !important;
  border-color: #E90000 !important;
}
.btn:hover, button:hover { filter: brightness(1.12); }
.status { background: #292020 !important; color: #F5DADA !important; border-color: #633030 !important; }
.status strong { color: #FFFFFF !important; }
.asset-local-pill { background: #292020 !important; color: #F5DADA !important; border-color: #633030 !important; }
.toast { background: #E90000 !important; color: #FFFFFF !important; }
hr, .divider { border-color: #666666 !important; }
/* Keep the actual phone/app previews independent from the website's dark theme. */
